import{_ as o,l as n,o as e,c as l,v as r,p as s,x as t,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"覆盖索引扫描","description":"","frontmatter":{"title":"覆盖索引扫描","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/covering-index.md","filePath":"cs/covering-index.md","lastUpdated":1789023840000}'),p={name:"cs/covering-index.md"};function E(_,a,m,A,u,B){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="覆盖索引扫描" tabindex="-1">覆盖索引扫描 <a class="header-anchor" href="#覆盖索引扫描" aria-label="Permalink to &quot;覆盖索引扫描&quot;">​</a></h1><div class="epigraph"><p>若查询需要的列都在索引键（或包含列）里，扫描可以停在索引页，不必回表取堆行。</p><footer>—— 据 Ramakrishnan and Gehrke 对索引只扫描；Date 对物理独立性对照</footer></div><p><a href="/cs/views-materialize">上一课</a>把宽接口收成视图或物化。本课不重做维护。缺口是物理访问：B+ 即将在后课展开，但优化器已经需要「覆盖」这一概念——二级索引通常只存键与 rid，回表随机 I/O 很贵。覆盖则叶子上已有投影所需列。页与槽下一课才讲记录布局。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>视图课留下逻辑宽表。执行仍要选访问路径。二级索引查找后用 rid 回堆，等于随机读。若 <code>SELECT</code> 的列是索引键的子集（或引擎支持 INCLUDE 列），索引叶子已是覆盖投影，范围扫描顺序 I/O。缺口是<strong>何时可以不做堆取</strong>，不是 B+ 分裂算法。</p><p><span class="marginnote">覆盖是物理设计：多一列进索引，更新变重、叶子变宽。与物化视图不同，它仍是一种索引，不是另一张用户表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计划里出现 Index-Only Scan：过滤与投影都在索引结构上完成。过滤条件最好对准键前缀，否则退化成索引全扫。堆聚簇（主键顺序存行）是另一种「覆盖」亲戚：主键扫描即数据。本课不把每家 DBMS 的 INCLUDE 语法当标准。</p>',8)),(e(),s(h,null,{default:t(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%8A%95%E5%BD%B1%E5%88%97%E9%9B%86%E5%90%88%22%5D%20--%3E%20KEY%5B%22%E6%98%AF%E5%90%A6%E5%8C%85%E5%90%AB%E4%BA%8E%E7%B4%A2%E5%BC%95%22%5D%0A%20%20KEY%20--%3E%20ONLY%5B%22%E5%8F%AA%E6%89%AB%E7%B4%A2%E5%BC%95%E5%8F%B6%22%5D%0A%20%20KEY%20--%3E%20HEAP%5B%22rid%20%E5%9B%9E%E8%A1%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>覆盖把<a href="/cs/algebra-reorder">选择投影</a> 的投影推进存储结构，是谓词下推的列方向版本。语义不变：结果关系相同。代价模型应计入叶子页数而不是堆页数。后课页槽解释 rid 指向什么。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入列存当主干替代。记录在页上如何安放，下一课页与槽。</p><p>后课默认：有的计划可以不回表。行仍是页上的槽化记录。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>覆盖索引避免回表，服务投影子集。</li><li>用空间与更新成本换 I/O。</li><li>页与槽下一课。</li><li>出处：Ramakrishnan and Gehrke；对照 Date 物理独立性。</li></ul>',7))])}const T=o(p,[["render",E]]);export{x as __pageData,T as default};
